# hypothesis: A TypeIs[Source] guard narrows a runtime-registered class to Source and accepts it at runtime, while a static checker rejects passing the same registered class where Source is required.
from abc import ABC, abstractmethod
from typing import TypeIs, assert_type, reveal_type


class Source(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        ...


class Fixed:
    @property
    def name(self) -> str:
        return 'fixed'


Source.register(Fixed)


def is_source(x: object) -> TypeIs[Source]:
    return isinstance(x, Source)


def label(x: Fixed | str) -> str:
    if is_source(x):
        reveal_type(x)
        return x.name
    return 'other'


def need_source(s: Source) -> str:
    return s.name


def bad(f: Fixed) -> str:
    return need_source(f)  # expect-error: Fixed is not statically a Source


assert_type(label(Fixed()), str)
assert label(Fixed()) == 'fixed'
assert label('x') == 'other'
assert issubclass(Fixed, Source)
assert bad(Fixed()) == 'fixed'
